-- (owners, transfers, RS / LR records, documents and files, legal records, loan, mutation, payments, tax, valuation),
-- so a new database shows the whole Legal flow. Added once: skipped when a land with this name already exists.
-- Remove it any time with Delete on the Land Register (removes all of its records and files).
-- Generated from the local database; master-list values (district, mouza, units, types …) are matched by their key.
IF NOT EXISTS (SELECT 1 FROM dbo.LegalLand WHERE LandName = N'Mondal family plot, Rajarhat (bought 2014)')
BEGIN
SET XACT_ABORT ON;
